/**
 * @file utils.ts
 * @output Utility functions for Selector
 * @position Utilities; used by Selector.tsx
 */

import { getSelectableOptionEntries } from "./selectableOptionEntries.js";
export { isOptionData, isDivider, isSection, normalizeOption } from "./optionShape.js";

/**
 * Get all selectable options (flattening sections)
 */
export function getSelectableOptions(options) {
  return getSelectableOptionEntries(options).map(entry => entry.item);
}